\label{m-sets of extensions}
Let $(T, \operatorname{\mathcal A}')$ be an  extension of  an elementary space $(X, \operatorname{\mathcal A})$, then 
$$\operatorname{\mathcal A}'=\{\text{cl}_T A : A\in \operatorname{\mathcal A} \}.$$

Let $(X, \operatorname{\mathcal A})$ be an elementary space. A nonempty family  $\mathcal F\subseteq \operatorname{\mathcal A}$  is called an $\operatorname{\mathcal A}$-filter on $X$ if it satisfies the following conditions:
\begin{enumerate}
\item $\emptyset\notin \mathcal F$,
\item if $A, B\in\mathcal F$, then $A\cap B\in\mathcal F$,
\item if $A\in\operatorname{\mathcal A}$ and $B\in\mathcal F$ where $B\subseteq A$, then $A\in\mathcal F$.
\end{enumerate}

\label{A-ultrafilter}
Let $(X, \operatorname{\mathcal A})$ be an elementary space and $\mathcal F$ be an $\operatorname{\mathcal A}$-filter on $X$. Then the following statements hold.
\begin{enumerate}
\item $\mathcal F$ is contained in an $\operatorname{\mathcal A}$-ultrafilter.
\item $\mathcal F$ is an $\operatorname{\mathcal A}$-ultrafilter if and only if  for each $A\in \operatorname{\mathcal A}$, either $A\in\mathcal F$ or $A^c\in \mathcal F$.
\item If $\mathcal F$ and $\mathcal G$  are distinct $\operatorname{\mathcal A}$-ultrafilters, then there are elementary sets 
$A_1\in \mathcal F$ and $A_2\in \mathcal G$ such that $A_1\cap A_2=\emptyset$. 
\end{enumerate}

\label{T-compactness}
If $(X, \operatorname{\mathcal A})$ is an elementary space, then the following are equivalent.
\begin{enumerate}
\item  The elementary space $(X, \operatorname{\mathcal A})$ is compact.
\item The topological  space $(X, \tau_{\operatorname{\mathcal A}})$ is compact.
\item  Every $\operatorname{\mathcal A}$-filter on $X$ is fixed.
\end{enumerate}
In this case, since $(X, \operatorname{\mathcal A})$ is reduced, then the intersection of members of any $\operatorname{\mathcal A}$-ultrafilter is a singleton.

\label{beta X}
Every (reduced) elementary space $(X, \operatorname{\mathcal A})$ has  a reduced compact    extension $(\beta_{\operatorname{\mathcal A}}X, \bar\operatorname{\mathcal A})$, which has the following properties.
\begin{enumerate}
\item Every elementary homomorphism from $X$ into any reduced compact elementary space $Y$ extends to an elementary homomorphism  on $\beta_{\operatorname{\mathcal A}}X$.
 \item Every $\operatorname{\mathcal A}$-measurable mapping $\varphi$ from $X$ into any compact topological space $Y$, has a continuous extension $\bar\varphi$ on $\beta_{\operatorname{\mathcal A}}X$.
\item Every  extension $(T, \operatorname{\mathcal A}')$ of $X$, is an elementary subspace of $\beta_{\operatorname{\mathcal A}}X$, i.e., $X\subseteq T\subseteq \beta_{\operatorname{\mathcal A}}X$, which means $(\beta_{\operatorname{\mathcal A}}X, \bar\operatorname{\mathcal A})$ is the maximum  extension of $X$.
\item If $(T, \operatorname{\mathcal A}')$ is an elementary extension of $X$, then $\beta_{\operatorname{\mathcal A}'}T=\beta_{\operatorname{\mathcal A}}X$.
\item For any two elementary sets $A, B\in \operatorname{\mathcal A}$, we have
$$\text{cl}_{\beta_{\operatorname{\mathcal A}}X}(A\cap B)=\text{cl}_{\beta_{\operatorname{\mathcal A}}X} A\cap \text{cl}_{\beta_{\operatorname{\mathcal A}}X} B.$$
\end{enumerate}

\label{beta_AX=beta X}
Let $(X, \operatorname{\mathcal A})$ be an elementary space. Then the following statements are equivalent.
\begin{enumerate}
\item $\beta_{\operatorname{\mathcal A}}X=\beta X$.
\item Any two disjoint zero-sets of $X$ separated by two disjoint elementary sets.
\item $M^*(X, \operatorname{\mathcal A})=C^*(X, \tau_{\operatorname{\mathcal A}})$.
\item $M(X, \operatorname{\mathcal A})=C(X, \tau_{\operatorname{\mathcal A}})$.
\item $\operatorname{\mathcal A}= Z(X)$.
\end{enumerate}

We only need  to prove the necessity. Thus, let $Z(g)\subseteq Z(f)$ and define 
\begin{equation*}
h(x) = \left\{
\begin{array}{rl}
0 & \text{if } x \in Z(g)\\
\frac{1}{g(x)} & \text{if } x\notin Z(g)
\end{array} \right.
\end{equation*}
Now, it is enough to show that $h\in M(X, \operatorname{\mathcal A})$, as $f=ghf$. To prove this, let $U$ be an open subset of $\mathbb R$ and $t(x)=\frac{1}{x}\in C(\mathbb R\setminus\{0\})$. Then, $t^{-1}(U)$ is open in $\mathbb R$. It follows then $h^{-1}(U)= g^{-1}(t^{-1}(U))\cap \text{coz\,} g\in\operatorname{\mathcal A}$, whenever $0\notin U$ and   $h^{-1}(U)= Z(g)\cup (g^{-1}(t^{-1}(U\setminus\{0\}))\cap \text{coz\,} g)\in\operatorname{\mathcal A}$, if $0\in U$.

\label{value of f*}
Let $(X, \operatorname{\mathcal A})$ be  an elementary space and $f\in M(X, \operatorname{\mathcal A})$, then the following statements hold
\begin{enumerate}
\item $ f^*(p)=\infty$ if and only if $|M^p(f)|$ is infinitely large.
\item $ f^*(p)=r$ if and only if $|M^p(f)-r|$ is either infinitely small or zero.
\end{enumerate}

Let $(X, \tau)$ be  a realcompact  topological space then  the following statements hold.
\begin{enumerate}
\item $(X, \operatorname{\mathcal A}_z)$ is realcompact.
\item  If every closed set in $X$ is a $G_{\delta}$-set, then $(X, \mathscr B)$ is realcompact.
\end{enumerate}

\label{M is quotient of M*}
Let $(X, \operatorname{\mathcal A})$ be an elementary space. Then the following statements hold.
\begin{enumerate}
\item $M(X, \operatorname{\mathcal A})$ is a ring of quotients of $M^*(X, \operatorname{\mathcal A})$.
\item $M(X, \operatorname{\mathcal A})$ and $M^*(X, \operatorname{\mathcal A})$ have the same maximal ring of quotients. 
\item For any dense open subspace $V$ of $(X, \tau_{\operatorname{\mathcal A}})$
$$C_L(V):=\{f\in C(V) : f \text{ is locally constant} \},$$
is a ring of quotients of $M(X, \operatorname{\mathcal A})$.
\end{enumerate}

\begin{enumerate}
\item If $0\ne g\in M(X, \operatorname{\mathcal A})$, then $1+g^2$ is a unit element of $M(X, \operatorname{\mathcal A})$, by Lemma \ref{units}. Hence $f=1/(1+g^2)\in M^*(X, \operatorname{\mathcal A})$ and $0\ne gf\in M^*(X, \operatorname{\mathcal A})$.
\item This part follows from (1).
\item First note that, it is easy to see that $C_L(V)$ is a subring of $C(V)$. Next,
 since for any $f\in M(X, \operatorname{\mathcal A})$ and  $r\in\mathbb R$, $f^{-1}(r)\in\operatorname{\mathcal A}$, then $M(X, \operatorname{\mathcal A})\subseteq C_L(V)$. Now, let $0\ne f\in C_L(V)$. Thus there is $p\in V$ such that $f(p)=r\ne0$. Since  $V\subseteq X$ is a open, there is an elementary set $A_0\in \operatorname{\mathcal A}$ such that $p\in A_0\subseteq V$. On the other hand, there is $A_1\in\operatorname{\mathcal A}$ such that $f|_{A_1}=r$, as $f$ is locally constant. Thus, $0\ne f\chi_{A_0\cap A_1}=r\chi_{A_0\cap A_1}\in M(X, \operatorname{\mathcal A})$, i.e., $C_L(V)$ is a ring of quotients of $M(X, \operatorname{\mathcal A})$.
\end{enumerate}

\label{M=C(X)}
Let $(X, \operatorname{\mathcal A})$ be an elementary space, then the following are equivalent.
\begin{enumerate}
\item $M(X, \operatorname{\mathcal A})\simeq C(X, \tau_{\operatorname{\mathcal A}})$.
\item $\operatorname{\mathcal A}$ is a $\sigma$-algebra and $\operatorname{\mathcal A}\simeq Z(X)$, as Boolean algebras.
\end{enumerate}

(1) $\Rightarrow$ (2). Suppose that $\psi : M(X, \operatorname{\mathcal A})\to C(X, \tau_{\operatorname{\mathcal A}})$ is a ring isomorphism. Then, $\psi$ takes real maximal ideals of $M(X,\operatorname{\mathcal A})$ to real maximal ideals of $C(X,\tau_{\operatorname{\mathcal A}})$ and vice-versa. In other words,    $\psi$ defines a one to one  mapping $\varphi$ from $\upsilon_{\operatorname{\mathcal A}}X$ onto $\upsilon X$ where for any $p\in\upsilon_{\operatorname{\mathcal A}}X$,
$$M^{\varphi(p)}=\{f\in C(X) : \psi^{-1}(f)\in M^p\}.$$
Here, $M^p $ (resp., $M^{\varphi(p)}$) is the real maximal ideal of $M(X,\operatorname{\mathcal A})$ (resp., $C(X, \tau_{\operatorname{\mathcal A}})$) corresponding to $p\in\upsilon_{\operatorname{\mathcal A}}X$ (resp., $\varphi(p)\in\upsilon X$). Moreover, using \cite[Theorem 7.3]{GJ} and Corollary \ref{G-K theorem},  for any $f\in M(X,\operatorname{\mathcal A})$ we have
\begin{align*}
\varphi(\text{cl}_{\upsilon_{\operatorname{\mathcal A}}X}Z(f))&=\{\varphi(p) : p\in \text{cl}_{\upsilon_{\operatorname{\mathcal A}}X}Z(f)\} \\
&=\{\varphi(p) : f\in M^p \} \\
&=\{q\in\upsilon X : \psi(f)\in M^q\}=\text{cl}_{\upsilon X}Z(\psi(f)). \tag{1}
\end{align*}
Now, define $\phi: \operatorname{\mathcal A}\to Z(X)$ by $\phi(A)=\varphi(\text{cl}_{\upsilon_{\operatorname{\mathcal A}}X}A)\cap X=Z(\psi(f))$, where $A=Z(f)$ for some $f\in M(X, \operatorname{\mathcal A})$. Using (1),  $\phi$    is a well-defined  one to one mapping and it is clearly onto. Moreover, by   Corollary \ref{beta X}(5) and  since $\varphi$ is one to one, for any $A, B\in \operatorname{\mathcal A}$, we have
\begin{align*}
\phi(A\cap B) &=\varphi(\text{cl}_{\upsilon_{\operatorname{\mathcal A}}X}(A\cap B))\cap X\\
&=\varphi(\text{cl}_{\upsilon_{\operatorname{\mathcal A}}X}A\cap \text{cl}_{\upsilon_{\operatorname{\mathcal A}}X}B)\cap X\\
&=\varphi(\text{cl}_{\upsilon_{\operatorname{\mathcal A}}X}A)\cap \varphi(\text{cl}_{\upsilon_{\operatorname{\mathcal A}}X}B)\cap X\\
&= \phi(A)\cap \phi(B).
\end{align*}
A similar argument shows that $\phi(A\cup B)= \phi(A)\cup \phi(B)$ and $\phi(A^c)=\phi(A)^c$, as $\varphi$ is onto as well. This is show that $\phi$ is a Boolean algebra isomorphism, see also \cite[2.8]{W1}. Finally, using \cite[1.14(a)]{GJ},  $Z(X)$ is closed under countable intersection and  by \cite[Theorem 8.7(IV)]{GJ}, for any countable family of elementary sets $\{A_n\}_{n\in\mathbb N}$, we have 
$$\varphi(\bigcap_{n=1}^\infty\text{cl}_{\upsilon_{\operatorname{\mathcal A}} X}A_n)=\bigcap_{n=1}^\infty\varphi(\text{cl}_{\upsilon_{\operatorname{\mathcal A}} X}A_n)=\bigcap_{n=1}^\infty\text{cl}_{\upsilon X}Z_n=\text{cl}_{\upsilon X}Z_0,$$
where $Z_n=\phi(A_n)$ and $Z_0=\bigcap_{n=1}^\infty Z_n$. It follows then $\text{cl}_{\upsilon_{\operatorname{\mathcal A}} X}A_0=\bigcap_{n=1}^\infty\text{cl}_{\upsilon_{\operatorname{\mathcal A}} X}A_n$ or equivalently $A_0=\bigcap_{n=1}^{\infty}A_n$, where $A_0=\phi^{-1}(Z_0)\in\operatorname{\mathcal A}$. This means that $\operatorname{\mathcal A}$ is closed under countable intersections (unions), i.e., $\operatorname{\mathcal A}$ is a $\sigma$-algebra.

(2) $\Rightarrow$ (1). Let $\phi: \operatorname{\mathcal A}\to Z(X)$ be the Boolean isomorphism. Thus using Lemma \ref{A-ultrafilter}, \cite[Theorem 5.14]{GJ} and \cite[Theorem 3.9]{ABS}, it is easy to see that,  the image of every real $\operatorname{\mathcal A}$-ultrafilter is a real $z$-ultrafilter. In other words, $\phi$ defines a one to one mapping $\varphi$ from $\upsilon_{\operatorname{\mathcal A}}X$ onto $\upsilon X$ with the following property:
\begin{align*}
\varphi(\text{cl}_{\upsilon_{\operatorname{\mathcal A}}X}A)=\text{cl}_{\upsilon X}\phi(A) \;\;\;\text{, for any } A\in\operatorname{\mathcal A}. \tag{2}
\end{align*}
Now, define $\psi: C(\upsilon X)\to M(\upsilon_{\operatorname{\mathcal A}}X, \bar\operatorname{\mathcal A}_R)$ by $\psi(f)=f\circ\varphi$. Using property (2), $f\circ\varphi^{-1}(U)\in\bar\operatorname{\mathcal A}_R$, for   any open subset $U$ of $\mathbb R$. Note that the zero-sets of  $\upsilon X$ are of the form $\text{cl}_{\upsilon X} Z$, for some $Z\in Z(X)$, by \cite[Remark 8.8(b)]{GJ}. This means that $\psi$ is well defined and since $\varphi$ is invertible, $\psi$ is one to one and onto. Moreover, clearly, $\psi$ is a ring homomorphism and therefore $C(\upsilon X)\simeq M(\upsilon_{\operatorname{\mathcal A}}X, \bar\operatorname{\mathcal A}_R)$. Now the result follows from \cite[Remark 8.8(a)]{GJ} and the argument after Corollary \ref{uX properties}.

\label{M=C(uX)}
Let $(X, \operatorname{\mathcal A})$ be a measurable space, then the following are equivalent.
\begin{enumerate}
\item $M(X, \operatorname{\mathcal A})\simeq C(Y)$, for some (topological) $P$-space $Y$.
\item $M(X, \operatorname{\mathcal A})\simeq C(\upsilon_{\operatorname{\mathcal A}}X)$, by the mapping $f\to f^{\upsilon_{\operatorname{\mathcal A}}}$.
\item $\bar\operatorname{\mathcal A}_R=Z(\upsilon_{\operatorname{\mathcal A}}X)$.
\end{enumerate}
